const RANGE = /^[ \t]*(?:(\d+)-(\d*)|-(\d+))[ \t]*$/;

const toSafe = (digits) => {
  const n = Number(digits);
  if (!Number.isSafeInteger(n)) throw new TypeError(`Unsafe integer in range: ${digits}`);
  return n;
};

export const parseRanges = (header, size) => {
  if (typeof header !== 'string') throw new TypeError('Header must be a string');
  if (!Number.isSafeInteger(size) || size < 0) throw new TypeError('Size must be a nonnegative safe integer');
  if (!header.startsWith('bytes=')) throw new TypeError('Invalid range unit');
  const result = [];
  for (const part of header.slice(6).split(',')) {
    const m = RANGE.exec(part);
    if (!m) throw new TypeError(`Invalid range: ${part}`);
    if (m[3] !== undefined) {
      const n = toSafe(m[3]);
      if (n === 0 || size === 0) continue;
      result.push([size - Math.min(n, size), size - 1]);
      continue;
    }
    const start = toSafe(m[1]);
    let end = m[2] === '' ? undefined : toSafe(m[2]);
    if (end !== undefined && start > end) throw new TypeError(`Reversed range: ${part}`);
    if (start >= size) continue;
    if (end === undefined || end > size - 1) end = size - 1;
    result.push([start, end]);
  }
  return result;
};

