export const parseRanges = (header, size) => {
  if (typeof header !== 'string') throw new TypeError('Range header must be a string');
  if (!Number.isSafeInteger(size) || size < 0) throw new TypeError('size must be a nonnegative safe integer');
  if (!header.startsWith('bytes=')) throw new TypeError('Range header must start with "bytes="');

