  for (const part of header.slice(6).split(',')) {
    const m = RANGE.exec(part);
    if (!m) throw new TypeError(`Invalid range: ${JSON.stringify(part)}`);

    if (m[3] !== undefined) {
      const n = toSafe(m[3]);
      if (n === 0 || size === 0) continue;
      ranges.push([size - Math.min(n, size), size - 1]);
      continue;
    }

    const start = toSafe(m[1]);
    const end = m[2] === '' ? undefined : toSafe(m[2]);
    if (end !== undefined && end < start) throw new TypeError(`Reversed range: ${part.trim()}`);
    if (start >= size) continue;
    ranges.push([start, end === undefined ? size - 1 : Math.min(end, size - 1)]);
  }
  return ranges;
};

