export function parseCsv(text) {
  if (typeof text !== 'string') throw new TypeError('parseCsv expects a string');
  const rows = [];
  if (text === '') return rows;
  let row = [];
  let field = '';
  let i = 0;
  const n = text.length;
  // state: 'start' (beginning of field), 'unquoted', 'quoted', 'afterQuote'
  let state = 'start';

  const endRow = () => {
    row.push(field);
    rows.push(row);
    row = [];
    field = '';
    state = 'start';
  };

  while (i < n) {
    const c = text[i];
    if (state === 'quoted') {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        state = 'afterQuote';
      } else {
        field += c;
      }
      i++;
      continue;
    }
    if (c === ',') {
      row.push(field);
      field = '';
      state = 'start';
      i++;
    } else if (c === '\n') {
      endRow();
      i++;
    } else if (c === '\r') {
      if (text[i + 1] !== '\n') throw new SyntaxError(`Bare CR at position ${i}`);
      endRow();
      i += 2;
    } else if (state === 'afterQuote') {
      throw new SyntaxError(`Unexpected character after closing quote at position ${i}`);
    } else if (c === '"') {
      if (state !== 'start') throw new SyntaxError(`Misplaced quote at position ${i}`);
      state = 'quoted';
      i++;
    } else {
      field += c;
      state = 'unquoted';
      i++;
    }
  }

  if (state === 'quoted') throw new SyntaxError('Unterminated quoted field');
  // A single terminal row separator does not add a row.
  const last = text[n - 1];
  if (!(state === 'start' && row.length === 0 && (last === '\n'))) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

