export function parseCsv(text) {
  if (typeof text !== 'string') throw new TypeError('parseCsv expects a string');
  const rows = [];
  const n = text.length;
  if (n === 0) return rows;
  let row = [];
  let i = 0;
  for (;;) {
    // Start of a field.
    let field = '';
    if (text[i] === '"') {
      i++;
      for (;;) {
        if (i >= n) throw new SyntaxError('Unterminated quoted field');
        const c = text[i];
        if (c === '"') {
          if (text[i + 1] === '"') { field += '"'; i += 2; }
          else { i++; break; }
        } else { field += c; i++; }
      }
      if (i < n && text[i] !== ',' && text[i] !== '\n' && text[i] !== '\r') {
        throw new SyntaxError(`Unexpected character after closing quote at ${i}`);
      }
    } else {
      while (i < n) {
        const c = text[i];
        if (c === ',' || c === '\n' || c === '\r') break;
        if (c === '"') throw new SyntaxError(`Unexpected quote at ${i}`);
        field += c;
        i++;
      }
    }
    row.push(field);
    if (i >= n) { rows.push(row); return rows; }
    const c = text[i];
    if (c === ',') { i++; continue; }
    if (c === '\r') {
      if (text[i + 1] !== '\n') throw new SyntaxError(`Bare CR at ${i}`);
      i += 2;
    } else {
      i++;
    }
    rows.push(row);
    row = [];
    if (i >= n) return rows;
  }
}

