const define = (obj, key, value) =>
  Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });

const clone = (v) => {
  if (Array.isArray(v)) return v.map(clone);
  if (isObj(v)) {
    const out = {};
    for (const k of Object.keys(v)) define(out, k, clone(v[k]));
    return out;
  }
  return v;
};

export const deepMerge = (left, right) => {
  if (!isObj(left) || !isObj(right)) return clone(right);
  const out = clone(left);
  for (const k of Object.keys(right)) {
    const r = right[k];
    define(out, k, Object.hasOwn(out, k) ? deepMerge(out[k], r) : clone(r));
  }
  return out;
};

