export class Emitter {
  #listeners = new Map();

  #add(event, fn, once) {
    if (typeof fn !== 'function') throw new TypeError('listener must be a function');
    const rec = { fn, once, consumed: false };
    let list = this.#listeners.get(event);
    if (!list) this.#listeners.set(event, (list = []));
    list.push(rec);
    return () => this.#remove(event, rec);
  }

  #remove(event, rec) {
    const list = this.#listeners.get(event);
    if (!list) return false;
    const i = list.indexOf(rec);
    if (i === -1) return false;
    list.splice(i, 1);
    if (list.length === 0) this.#listeners.delete(event);
    return true;
  }

  on(event, fn) {
    return this.#add(event, fn, false);
  }

  once(event, fn) {
    return this.#add(event, fn, true);
  }

  emit(event, ...args) {
    const list = this.#listeners.get(event);
    if (!list) return 0;
    const snapshot = list.slice();
    let count = 0;
    for (const rec of snapshot) {
      if (rec.once) {
        if (rec.consumed) continue;
        rec.consumed = true;
        this.#remove(event, rec);
      }
      count++;
      rec.fn.apply(this, args);
    }
    return count;
  }
}

