export const mergeIntervals = intervals => {
  if (!Array.isArray(intervals)) throw new TypeError('intervals must be an array');
  const pairs = [];
  for (let i = 0; i < intervals.length; i++) {
    const pair = intervals[i];
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError(`interval at index ${i} must be a [start, end] pair`);
    }
    const start = pair[0];
    const end = pair[1];
    if (typeof start !== 'number' || typeof end !== 'number' ||
        !Number.isFinite(start) || !Number.isFinite(end)) {
      throw new TypeError(`interval at index ${i} must contain finite numbers`);
    }
    if (start > end) throw new TypeError(`interval at index ${i} is reversed`);
    pairs.push([start, end]);
  }
  pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const merged = [];
  for (const [start, end] of pairs) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1]) {
      if (end > last[1]) last[1] = end;
    } else {
      merged.push([start, end]);
    }
  }
  return merged;
};

