const MONEY = /^(-?)(\d+)(?:\.(\d{1,2}))?$/;

export function sumMoney(values) {
  if (values == null || typeof values[Symbol.iterator] !== 'function' || typeof values === 'string') {
    throw new TypeError('values must be an iterable of money strings');
  }
  let total = 0n;
  for (const v of values) {
    if (typeof v !== 'string') throw new TypeError('money value must be a string');
    const m = MONEY.exec(v);
    if (!m) throw new TypeError(`invalid money value: ${v}`);
    const cents = BigInt(m[2]) * 100n + BigInt((m[3] ?? '').padEnd(2, '0'));
    total += m[1] ? -cents : cents;
  }
  const neg = total < 0n;
  const abs = neg ? -total : total;
  const s = abs.toString().padStart(3, '0');
  return `${neg ? '-' : ''}${s.slice(0, -2)}.${s.slice(-2)}`;
}

