    assertFinite('ttl', ttl);
    if (ttl < 0) throw new TypeError('ttl must be >= 0');
    assertFinite('now', now);

    this.#purge(now);
    const existed = this.#data.delete(key);
    if (ttl === 0) return this;

    this.#data.set(key, { value, expires: now + ttl });
    if (!existed) {
      while (this.#data.size > this.#capacity) {
        this.#data.delete(this.#data.keys().next().value);
      }
