// Parses an HTTP Range header (`bytes=<range>[,<range>...]`) against a resource
// of `size` bytes. Returns inclusive [start, end] pairs in request order.
export function parseRanges(header, size) {
  if (typeof header !== 'string') throw new TypeError('header must be a string');
  if (!Number.isSafeInteger(size) || size < 0) {
    throw new TypeError('size must be a nonnegative safe integer');
  }
  if (!header.startsWith('bytes=')) throw new TypeError('header must start with "bytes="');

  const rest = header.slice(6);
  const ranges = [];

  for (const raw of rest.split(',')) {
    const part = raw.replace(/^[ \t]+|[ \t]+$/g, '');
    const match = /^(\d*)-(\d*)$/.exec(part);
    if (!match || (match[1] === '' && match[2] === '')) {
      throw new TypeError(`invalid range: "${part}"`);
    }

    const [, first, last] = match;
    const start = first === '' ? null : Number(first);
    const end = last === '' ? null : Number(last);
    if ((start !== null && !Number.isSafeInteger(start)) ||
        (end !== null && !Number.isSafeInteger(end))) {
      throw new TypeError(`range value out of bounds: "${part}"`);
    }

    if (start === null) {
      // Suffix range `-n`: the last n bytes.
      if (end === 0 || size === 0) continue;
      ranges.push([size - Math.min(end, size), size - 1]);
    } else if (end === null) {
      // Open range `a-`: from a to the end of the resource.
      if (start >= size) continue;
      ranges.push([start, size - 1]);
    } else {
      // Explicit range `a-b`.
      if (start > end) throw new TypeError(`range start exceeds end: "${part}"`);
      if (start >= size) continue;
      ranges.push([start, Math.min(end, size - 1)]);
    }
  }

  return ranges;
}

