const RANGE_PIECE = /^(\d*)-(\d*)$/;

// Parses an HTTP `Range: bytes=...` header into inclusive [start, end] pairs
// for a representation of `size` bytes. Ranges are returned in request order
// and are not merged. Unsatisfiable ranges are skipped; syntax errors throw.
export function parseRanges(header, size) {
  if (typeof header !== 'string') throw new TypeError('header must be a string');
  if (!Number.isSafeInteger(size) || size < 0) throw new TypeError('size must be a nonnegative safe integer');
  if (!header.startsWith('bytes=')) throw new TypeError('header must start with "bytes="');

  const pieces = header.slice('bytes='.length).split(',');

  // Validate every piece before deciding which ones to skip, so a syntax
  // error anywhere throws even when the range would be skipped.
  const parsed = pieces.map((raw) => {
    const piece = raw.replace(/^[ \t]+|[ \t]+$/g, '');
    if (piece === '') throw new TypeError('empty range in header');

    const match = RANGE_PIECE.exec(piece);
    if (!match) throw new TypeError(`invalid range: ${piece}`);

    const [, startStr, endStr] = match;
    if (startStr === '' && endStr === '') throw new TypeError('invalid range: "-"');

    const toInt = (str) => {
      if (str === '') return null;
      const n = Number(str);
      if (!Number.isSafeInteger(n)) throw new TypeError(`range value out of range: ${str}`);
      return n;
    };

    const start = toInt(startStr);
    const end = toInt(endStr);
    if (start !== null && end !== null && start > end) throw new TypeError(`invalid range: ${piece}`);
    return { start, end };
  });

  const ranges = [];
  for (const { start, end } of parsed) {
    if (start !== null && end !== null) {
      if (start >= size) continue;
      ranges.push([start, Math.min(end, size - 1)]);
    } else if (start !== null) {
      if (start >= size) continue;
      ranges.push([start, size - 1]);
    } else {
      if (end === 0 || size === 0) continue;
      ranges.push([size - Math.min(end, size), size - 1]);
    }
  }
  return ranges;
}

