export const parseRanges = (header, size) => {
  if (typeof header !== 'string') {
    throw new TypeError('Range header must be a string');
  }
  if (!Number.isSafeInteger(size) || size < 0) {
    throw new TypeError('size must be a non-negative safe integer');
  }
  if (!header.startsWith('bytes=')) {
    throw new TypeError('Range header must start with "bytes="');
  }

  const parts = header.slice('bytes='.length).split(',');

  // Validate and parse every part before resolving any of them against size
  const descriptors = parts.map((raw) => {
    const part = raw.replace(/^[ \t]+|[ \t]+$/g, '');
    const match = PART_PATTERN.exec(part);
    if (!match) {
      throw new TypeError(`Invalid range: "${part}"`);
    }

    if (match[3] !== undefined) {
      const n = Number(match[3]);
      if (!Number.isSafeInteger(n)) {
        throw new TypeError(`Range value out of range: "${part}"`);
      }
      return { suffix: true, n };
    }

    const start = Number(match[1]);
    if (!Number.isSafeInteger(start)) {
      throw new TypeError(`Range value out of range: "${part}"`);
    }
    if (match[2] === '') {
      return { suffix: false, start, end: null };
    }
    const end = Number(match[2]);
    if (!Number.isSafeInteger(end)) {
      throw new TypeError(`Range value out of range: "${part}"`);
    }
    if (start > end) {
      throw new TypeError(`Range start is greater than end: "${part}"`);
    }
    return { suffix: false, start, end };
  });

  if (size === 0) {
    return [];
  }

  const ranges = [];
  for (const d of descriptors) {
    if (d.suffix) {
      if (d.n === 0) continue;
      const len = Math.min(d.n, size);
      ranges.push([size - len, size - 1]);
    } else {
      if (d.start >= size) continue;
      const end = d.end === null ? size - 1 : Math.min(d.end, size - 1);
      ranges.push([d.start, end]);
    }
  }
  return ranges;
};

