// States: 'start' (at beginning of a field), 'unquoted', 'quoted' (inside quotes),
// 'closed' (just past a closing quote; only a delimiter or row end may follow).
export function parseCsv(text) {
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let state = 'start';
  let quoteStart = -1;
  let i = 0;

  const endField = () => {
    row.push(field);
    field = '';
    state = 'start';
  };
  const endRow = () => {
    endField();
    rows.push(row);
    row = [];
  };

  while (i < text.length) {
    const c = text[i];

    if (state === 'quoted') {
      if (c === '"') {
        if (text[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          state = 'closed';
          i++;
        }
      } else {
        field += c;
        i++;
      }
      continue;
    }

    if (c === ',') {
      endField();
      i++;
    } else if (c === '\n') {
      endRow();
      i++;
    } else if (c === '\r') {
      if (text[i + 1] !== '\n') {
        throw new SyntaxError(`Bare carriage return at position ${i} (only \\r\\n is allowed as a row separator)`);
      }
      endRow();
      i += 2;
    } else if (state === 'closed') {
      throw new SyntaxError(`Unexpected character ${JSON.stringify(c)} after closing quote at position ${i}`);
    } else if (c === '"') {
      if (state !== 'start') {
        throw new SyntaxError(`Unexpected quote inside unquoted field at position ${i}`);
      }
      state = 'quoted';
      quoteStart = i;
      i++;
    } else {
      field += c;
      state = 'unquoted';
      i++;
    }
  }

  if (state === 'quoted') {
    throw new SyntaxError(`Unterminated quoted field starting at position ${quoteStart}`);
  }

  // Pending content exists unless the input ended right after a row separator.
  if (state !== 'start' || row.length > 0) {
    endField();
    rows.push(row);
  }

  return rows;
}

