export function parseCsv(text) {
  text = String(text);
  if (text === '') return [];

  const rows = [];
  let row = [];
  let field = '';
  let fieldStart = true;
  let justEndedRow = false;
  let i = 0;
  const n = text.length;

  while (i < n) {
    const c = text[i];
    justEndedRow = false;

    if (c === '"' && fieldStart) {
      i++;
      let closed = false;
      while (i < n && !closed) {
        const q = text[i];
        if (q === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            i++;
            closed = true;
          }
        } else {
          field += q;
          i++;
        }
      }
      if (!closed) throw new SyntaxError('Unterminated quoted field');
      const after = text[i];
      if (!(i >= n || after === ',' || after === '\n' || (after === '\r' && text[i + 1] === '\n'))) {
        throw new SyntaxError('Unexpected character after closing quote');
      }
      fieldStart = false;
    } else if (c === '"') {
      throw new SyntaxError('Unexpected quote');
    } else if (c === ',') {
      row.push(field);
      field = '';
      fieldStart = true;
      i++;
    } else if (c === '\n') {
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      fieldStart = true;
      i++;
      justEndedRow = true;
    } else if (c === '\r') {
      if (text[i + 1] !== '\n') throw new SyntaxError('Bare CR outside quotes');
      row.push(field);
      rows.push(row);
      row = [];
      field = '';
      fieldStart = true;
      i += 2;
      justEndedRow = true;
    } else {
      field += c;
      fieldStart = false;
      i++;
    }
  }

  if (!justEndedRow) {
    row.push(field);
    rows.push(row);
  }
  return rows;
}

