const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

// Plain assignment to '__proto__' would invoke the inherited setter and change the prototype,
// so every write goes through defineProperty to keep keys as ordinary data properties.
const defineData = (obj, key, value) => {
  Object.defineProperty(obj, key, { value, writable: true, enumerable: true, configurable: true });
};

const clone = (v) => {
  if (Array.isArray(v)) return v.map(clone);
  if (isPlainObject(v)) {
    const out = {};
    for (const k of Object.keys(v)) defineData(out, k, clone(v[k]));
    return out;
  }
  return v;
};

export function deepMerge(left, right) {
  if (isPlainObject(left) && isPlainObject(right)) {
    const out = {};
    for (const k of Object.keys(left)) {
      if (Object.prototype.hasOwnProperty.call(right, k)) {
        defineData(out, k, deepMerge(left[k], right[k]));
      } else {
        defineData(out, k, clone(left[k]));
      }
    }
    for (const k of Object.keys(right)) {
      if (!Object.prototype.hasOwnProperty.call(left, k)) {
        defineData(out, k, clone(right[k]));
      }
    }
    return out;
  }
  return clone(right);
}

export default deepMerge;

