export class Emitter {
  #events = new Map();

  #add(event, fn, once) {
    if (typeof fn !== 'function') throw new TypeError('listener must be a function');
    const record = { fn, once, fired: false };
    if (!this.#events.has(event)) this.#events.set(event, []);
    this.#events.get(event).push(record);
    return () => this.#remove(event, record);
  }

  #remove(event, record) {
    const list = this.#events.get(event);
    if (!list) return;
    const index = list.indexOf(record);
    if (index === -1) return;
    list.splice(index, 1);
    if (list.length === 0) this.#events.delete(event);
  }

  on(event, fn) {
    return this.#add(event, fn, false);
  }

  once(event, fn) {
    return this.#add(event, fn, true);
  }

  emit(event, ...args) {
    const list = this.#events.get(event);
    if (!list) return 0;
    const snapshot = list.slice();
    let count = 0;
    for (const rec of snapshot) {
      if (rec.once) {
        if (rec.fired) continue;
        rec.fired = true;
        this.#remove(event, rec);
      }
      count++;
      rec.fn.apply(this, args);
    }
    return count;
  }
}

