export class Emitter {
  constructor() {
    // event key -> array of { fn, once, fired } registration records
    this._events = new Map();
  }

  on(event, fn) {
    return this._add(event, fn, false);
  }

  once(event, fn) {
    return this._add(event, fn, true);
  }

  _add(event, fn, once) {
    if (typeof fn !== 'function') {
      throw new TypeError('listener must be a function');
    }
    // A fresh record per registration keeps duplicate `fn` registrations independent.
    const record = { fn, once, fired: false };
    let list = this._events.get(event);
    if (!list) {
      list = [];
      this._events.set(event, list);
    }
    list.push(record);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      this._remove(event, record);
    };
  }

  _remove(event, record) {
    const list = this._events.get(event);
    if (!list) return;
    // Match by record identity, not by fn, so only this registration is removed.
    const index = list.indexOf(record);
    if (index === -1) return;
    list.splice(index, 1);
    if (list.length === 0) {
      this._events.delete(event);
    }
  }

  emit(event, ...args) {
    const list = this._events.get(event);
    if (!list) return 0;
    // Iterate over a snapshot so listeners added or removed mid-emit don't shift this emit.
    const snapshot = list.slice();
    let count = 0;
    for (const rec of snapshot) {
      if (rec.once) {
        // Already consumed by a nested emit: skip it.
        if (rec.fired) continue;
        // Mark and unregister before calling so reentrant emits cannot run it again.
        rec.fired = true;
        this._remove(event, rec);
      }
      count++;
      rec.fn.apply(this, args);
    }
    return count;
  }

  listenerCount(event) {
    const list = this._events.get(event);
    return list ? list.length : 0;
  }
}

