export function mergeIntervals(intervals) {
  // Validate everything before doing any other work
  if (!Array.isArray(intervals)) {
    throw new TypeError('intervals must be an array');
  }
  for (let i = 0; i < intervals.length; i++) {
    const p = intervals[i];
    if (!(Array.isArray(p) && p.length === 2)) {
      throw new TypeError(`interval at index ${i} must be a [start, end] pair`);
    }
    const s = p[0], e = p[1];
    if (!(typeof s === 'number' && Number.isFinite(s) && typeof e === 'number' && Number.isFinite(e))) {
      throw new TypeError(`interval at index ${i} must have finite number bounds`);
    }
    if (s > e) {
      throw new TypeError(`interval at index ${i} has start greater than end`);
    }
  }

  // Copy so the input is never mutated, then sort the copies
  const copies = intervals.map(p => [p[0], p[1]]);
  copies.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  // Merge overlapping and touching intervals
  const result = [];
  for (const cur of copies) {
    const last = result[result.length - 1];
    if (!last || cur[0] > last[1]) {
      result.push([cur[0], cur[1]]);
    } else {
      last[1] = Math.max(last[1], cur[1]);
    }
  }
  return result;
}

