export async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new TypeError('limit must be a positive integer');
  }
  if (typeof fn !== 'function') throw new TypeError('fn must be a function');
  const list = Array.from(items);          // snapshot; never mutate caller's array
  const results = new Array(list.length);
  if (list.length === 0) return results;   // []
  let next = 0;
  let failed = false;
  const worker = async () => {
    while (!failed && next < list.length) {
      const i = next++;
      try {
        // fn is called inside try, so a synchronous throw is caught too; await handles plain values
        results[i] = await fn(list[i], i);
      } catch (err) {
        failed = true;                     // stop other workers from starting new items
        throw err;                         // original error, not wrapped
      }
    }
  };
  const workers = [];
  for (let w = 0; w < Math.min(limit, list.length); w++) workers.push(worker());
  await Promise.all(workers);              // rejects with the first error observed
  return results;
}

