export async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new TypeError('limit must be a positive integer');
  }
  const list = Array.from(items);          // snapshot; never mutate input
  const results = new Array(list.length);
  if (list.length === 0) return results;   // []
  return new Promise((resolve, reject) => {
    let next = 0, active = 0, done = 0, failed = false;
    const launch = () => {
      while (!failed && active < limit && next < list.length) {
        const i = next++;
        active++;
        let p;
        try {
          p = Promise.resolve(fn(list[i], i)); // a sync throw goes to catch
        } catch (err) {
          active--;
          failed = true;
          reject(err);
          return;
        }
        p.then(
          value => {
            active--;
            if (failed) return;
            results[i] = value;
            if (++done === list.length) resolve(results);
            else launch();
          },
          err => {
            active--;
            if (!failed) { failed = true; reject(err); }
          }
        );
      }
    };
    launch();
  });
}

