const MONEY_RE = /^(-)?(\d+)(?:\.(\d{1,2}))?$/;

export const sumMoney = values => {
  if (values == null || typeof values === 'string' || typeof values[Symbol.iterator] !== 'function') {
    throw new TypeError('values must be an iterable of money strings');
  }

  let total = 0n;
  for (const v of values) {
    const m = typeof v === 'string' ? MONEY_RE.exec(v) : null;
    if (!m) throw new TypeError('invalid money value');

    const [, sign, intPart, frac] = m;
    let cents = BigInt(intPart) * 100n + BigInt((frac ?? '').padEnd(2, '0'));
    if (sign) cents = -cents;
    total += cents;
  }

  const neg = total < 0n;
  const abs = neg ? -total : total;
  const intStr = (abs / 100n).toString();
  const fracStr = (abs % 100n).toString().padStart(2, '0');
  return (neg ? '-' : '') + intStr + '.' + fracStr;
};

