const MONEY_RE = /^(-?)(\d+)(?:\.(\d{1,2}))?$/;

function toCents(value) {
  if (typeof value !== 'string') throw new TypeError('Invalid money value');
  const m = MONEY_RE.exec(value);
  if (m === null) throw new TypeError(`Invalid money value: ${value}`);
  const [, sign, intPart, frac = ''] = m;
  const cents = BigInt(intPart + frac.padEnd(2, '0'));
  return sign === '-' ? -cents : cents;
}

export function sumMoney(values) {
  if (values == null || typeof values[Symbol.iterator] !== 'function') {
    throw new TypeError('values must be iterable');
  }
  let total = 0n;
  for (const v of values) total += toCents(v);
  const negative = total < 0n;
  const digits = (negative ? -total : total).toString().padStart(3, '0');
  const result = `${digits.slice(0, -2)}.${digits.slice(-2)}`;
  return negative ? `-${result}` : result;
}

