  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) throw new Error('Edge must be an array of length 2');
    const [from, to] = edge;
    if (!index.has(from) || !index.has(to)) throw new Error('Unknown node');
    const i = index.get(from);
    const j = index.get(to);
