// Throws TypeError unless n is a finite number. Rejects strings, BigInt, NaN, ±Infinity, null and undefined.
function checkTime(n, name) {
  if (typeof n !== 'number' || !Number.isFinite(n)) {
    throw new TypeError(`${name} must be a finite number`);
  }
}

// Throws TypeError unless ttl is a finite, non-negative number.
function checkTtl(ttl) {
  checkTime(ttl, 'ttl');
  if (ttl < 0) {
    throw new TypeError('ttl must not be negative');
  }
}

export class TtlLru {
  #capacity;
  // key -> { value, expires }. Insertion order is recency order: the first key is the least recently used.
  #map = new Map();

  constructor(capacity) {
    if (typeof capacity !== 'number' || !Number.isInteger(capacity) || capacity <= 0) {
      throw new TypeError('capacity must be a positive integer');
    }
    this.#capacity = capacity;
  }

  // Removes every entry whose expiry has been reached (inclusive).
  #purge(now) {
    for (const [key, entry] of this.#map) {
      if (now >= entry.expires) {
        this.#map.delete(key);
      }
    }
  }

  set(key, value, ttl, now) {
    checkTtl(ttl);
    checkTime(now, 'now');

    this.#purge(now);

    if (ttl === 0) {
      this.#map.delete(key);
      return this;
    }

    // Delete before re-inserting so the key moves to the most-recent end.
    this.#map.delete(key);
    this.#map.set(key, { value, expires: now + ttl });

    while (this.#map.size > this.#capacity) {
      this.#map.delete(this.#map.keys().next().value);
    }
    return this;
  }

  get(key, now) {
    checkTime(now, 'now');

    const entry = this.#map.get(key);
    if (entry === undefined) {
      return undefined;
    }

    if (now >= entry.expires) {
      this.#map.delete(key);
      return undefined;
    }

    // Refresh recency by moving the key to the most-recent end.
    this.#map.delete(key);
    this.#map.set(key, entry);
    return entry.value;
  }
}

