const parseSpec = (part) => {
  const match = RANGE_PATTERN.exec(part.replace(/^[ \t]+|[ \t]+$/g, ''));
  if (!match) throw new TypeError(`invalid range: ${part}`);
  if (match[3] !== undefined) return { suffix: toSafeInteger(match[3]) };
  const start = toSafeInteger(match[1]);
