export function parseCsv(text) {
  const rows = [];
  if (text === '') return rows;

  const n = text.length;
  let i = 0;
  let row = [];

  for (;;) {
    let field = '';

    if (text[i] === '"') {
      // Quoted field: may contain commas, row separators, and doubled quotes.
      i++;
      for (;;) {
        if (i >= n) throw new SyntaxError('Unterminated quoted field');
        if (text[i] === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 2;
          } else {
            i++;
            break;
          }
        } else {
          field += text[i++];
        }
      }
      if (i < n && text[i] !== ',' && text[i] !== '\n' && text[i] !== '\r') {
        throw new SyntaxError('Unexpected character after closing quote');
      }
    } else {
      while (i < n && text[i] !== ',' && text[i] !== '\n' && text[i] !== '\r') {
        if (text[i] === '"') throw new SyntaxError('Quote is only valid at the start of a field');
        field += text[i++];
      }
    }

    row.push(field);

    if (i >= n) {
      rows.push(row);
      break;
    }

    if (text[i] === ',') {
      i++;
      continue;
    }

    // Row separator: LF or CRLF. A bare CR is invalid outside quotes.
    if (text[i] === '\r') {
      if (text[i + 1] !== '\n') throw new SyntaxError('Bare CR outside quoted field');
      i += 2;
    } else {
      i++;
    }
    rows.push(row);
    row = [];

    // A single terminal row separator does not start another row.
    if (i >= n) break;
  }

  return rows;
}

