export class Emitter {
  constructor() {
    // event -> array of registration records, in registration order
    this.listeners = new Map();
  }

  on(event, fn) {
    return this.#register(event, fn, false);
  }

  once(event, fn) {
    return this.#register(event, fn, true);
  }

  emit(event, ...args) {
    const list = this.listeners.get(event);
    if (!list) return 0;

    // Snapshot: listeners added or removed during this emit don't affect it.
    const snapshot = list.slice();
    let invoked = 0;
    for (const record of snapshot) {
      if (record.once) {
        // Skip once-listeners already consumed by a nested emit.
        if (record.consumed) continue;
        // Consume and unregister before running the callback so reentrant
        // emits can't invoke it again.
        record.consumed = true;
        this.#remove(event, record);
      }
      invoked++;
      record.fn(...args);
    }
    return invoked;
  }

  #register(event, fn, once) {
    const record = { fn, once, consumed: false };
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(record);
    return () => this.#remove(event, record);
  }

  #remove(event, record) {
    const list = this.listeners.get(event);
    if (!list) return;
    const index = list.indexOf(record);
    if (index !== -1) list.splice(index, 1);
    if (list.length === 0) this.listeners.delete(event);
  }
}

