export const mergeIntervals = intervals => {
  if (!Array.isArray(intervals)) throw invalid('intervals must be an array');

  // Copy and validate every pair up front so the input is never mutated and
  // holes or malformed entries are rejected rather than silently skipped.
  const pairs = [];
  for (let i = 0; i < intervals.length; i++) {
    const pair = intervals[i];
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw invalid(`interval ${i} must be a [start, end] pair`);
    }
    const [start, end] = pair;
    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      throw invalid(`interval ${i} must contain finite numbers`);
    }
    if (start > end) throw invalid(`interval ${i} has start greater than end`);
    pairs.push([start, end]);
  }

  pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [];
  for (const [start, end] of pairs) {
    const last = merged[merged.length - 1];
    // `<=` also merges touching boundaries, e.g. [1,2] and [2,3].
    if (last && start <= last[1]) {
      if (end > last[1]) last[1] = end;
    } else {
      merged.push([start, end]);
    }
  }
  return merged;
