export async function mapLimit(items, limit, fn) {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new TypeError('limit must be a positive integer');
  }
  const list = Array.from(items);
  const results = new Array(list.length);
  if (list.length === 0) return results;

  return new Promise((resolve, reject) => {
    let next = 0;
    let settled = 0;
    let failed = false;

    const runNext = () => {
      if (failed || next >= list.length) return;
      const index = next++;
      // The executor runs synchronously, so sync throws from fn become rejections.
      new Promise(done => done(fn(list[index], index))).then(
        value => {
          results[index] = value;
          settled++;
          if (settled === list.length) resolve(results);
          else runNext();
        },
        error => {
          if (!failed) {
            failed = true;
            reject(error);
          }
        },
      );
    };

    for (let i = 0; i < Math.min(limit, list.length); i++) runNext();
  });
}

