export const slug = text => {
  if (typeof text !== 'string') throw new TypeError('slug: input must be a string');
  return text
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
};

