// Lexicographic-by-position topological sort (Kahn's algorithm).
// At each step, the zero-indegree node that appears earliest in `nodes` is emitted.
export const topoSort = (nodes, edges) => {
  if (!Array.isArray(nodes)) throw new Error('nodes must be an array');
  if (!Array.isArray(edges)) throw new Error('edges must be an array');

  const index = new Map();
  nodes.forEach((node, i) => {
    if (typeof node !== 'string') throw new Error('nodes must be strings');
    if (index.has(node)) throw new Error(`duplicate node: ${node}`);
    index.set(node, i);
  });

  const n = nodes.length;
  const successors = Array.from({ length: n }, () => new Set());
  const indegree = new Array(n).fill(0);

  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) throw new Error('edges must be [from, to] pairs');
    const [from, to] = edge;
    if (!index.has(from)) throw new Error(`unknown node: ${from}`);
    if (!index.has(to)) throw new Error(`unknown node: ${to}`);
    const u = index.get(from);
    const v = index.get(to);
    if (successors[u].has(v)) continue; // duplicate edges count once
    successors[u].add(v);
    indegree[v] += 1;
  }

  const ready = [];
  for (let i = 0; i < n; i += 1) {
    if (indegree[i] === 0) ready.push(i);
  }

  const order = [];
  while (ready.length > 0) {
    // Pick the ready node with the smallest original position.
    let best = 0;
    for (let k = 1; k < ready.length; k += 1) {
      if (ready[k] < ready[best]) best = k;
    }
    const u = ready[best];
    ready[best] = ready[ready.length - 1];
    ready.pop();

    order.push(nodes[u]);
    for (const v of successors[u]) {
      indegree[v] -= 1;
      if (indegree[v] === 0) ready.push(v);
    }
  }

  if (order.length !== n) throw new Error('cycle detected');
  return order;
};

