// Map iteration order doubles as recency order: the first key is the least
// recently used, and refreshing a key means deleting and re-inserting it.
export class TtlLru {
  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity <= 0) {
      throw new TypeError('capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.entries = new Map();
  }

  set(key, value, ttl, now) {
    assertFiniteNumber(ttl, 'ttl');
    assertFiniteNumber(now, 'now');
    if (ttl < 0) {
      throw new TypeError('ttl must be >= 0');
    }

    this.purgeExpired(now);
    this.entries.delete(key);

    if (ttl === 0) {
      return;
    }

    this.entries.set(key, { value, expires: now + ttl });
    while (this.entries.size > this.capacity) {
      const lru = this.entries.keys().next().value;
      this.entries.delete(lru);
    }
  }

  get(key, now) {
    assertFiniteNumber(now, 'now');

    const entry = this.entries.get(key);
    if (entry === undefined) {
      return undefined;
    }
    if (now >= entry.expires) {
      this.entries.delete(key);
      return undefined;
    }

    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  purgeExpired(now) {
    for (const [key, entry] of this.entries) {
      if (now >= entry.expires) {
        this.entries.delete(key);
      }
    }
  }
}

