// Returns a new array with duplicates removed, keeping each value's first
// appearance. Equality is SameValueZero (Set semantics: NaN equals NaN, and
// +0 equals -0). The input array is never mutated.
export const unique=values=>{
  const seen=new Set();
  const result=[];
  for(const value of values){
    // Track membership with a Set for O(1) checks, but push the original value
    // so the first occurrence is returned exactly as it appeared (e.g. -0 stays -0).
    if(!seen.has(value)){
      seen.add(value);
      result.push(value);
    }
  }
  return result;
};
